package Q1;
import java.io.*;import java.util.*;
public class ATM{static class LowBalance extends Exception{LowBalance(String m){super(m);}}static void withdraw(String id,String raw,double balance)throws IOException,LowBalance{double amount=Double.parseDouble(raw);if(amount<=0)throw new IllegalArgumentException("Amount must be positive");if(amount>balance)throw new LowBalance("Insufficient balance");try(BufferedReader r=new BufferedReader(new FileReader("card-reader.txt"))){r.readLine();}System.out.println("Dispensed Rs "+amount+" for "+id);}public static void main(String[]x){try{withdraw("A100",x.length>0?x[0]:"100",500);}catch(NumberFormatException e){System.out.println("Invalid numeric amount");}catch(LowBalance e){System.out.println(e.getMessage());}catch(IOException e){System.out.println("Card reader error: "+e.getMessage());}finally{System.out.println("ATM session closed");}}}
